basic_instrumentation.go:
package main

import (
    "context"
    "log"
    threadify "github.com/ThreadifyDev/go-sdk"
)

func main() {
    ctx := context.Background()
    connection, err := threadify.Connect(ctx, "YOUR_API_KEY", threadify.WithServiceName("orders-service"), threadify.WithEngineURL("YOUR_ENGINE_URL"))
    if err != nil { log.Fatal(err) }
    defer connection.Close()
    thread, err := connection.Thread(ctx, "order:ORD-123", threadify.ThreadOptions{Label: "Order processing"})
    if err != nil { log.Fatal(err) }
    if _, err := thread.Step("order_received").AddContext(map[string]any{"order_id": "ORD-123"}).Success(ctx); err != nil { log.Fatal(err) }
}
